INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-001', '南航上充值一直不到账怎么办？', '校园卡充值常会有延迟，耐心等待；若长时间未到账，可向信息化处反映咨询，联系电话：84890123。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-002', '南航邮箱申请方法？', '可在南航办事大厅中申请，按照相关步骤办理即可。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-003', '怎么办游泳卡', '办卡流程：'||CHAR(10)||'到校医院体检，先前往保健科；'||CHAR(10)||'体检合格后，携带本人学生证（工作证）前往校园卡办理处，登记信息、采集照片、现金充值完成办卡。'||CHAR(10)||'办卡地点：游泳馆辅助 2 号口。'||CHAR(10)||'注意事项：充值仅支持现金；办卡时间：周一至周五 14:00-17:00，周六、周日不办理充值。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-004', '补办校园卡相关事宜？', '补办校园卡需缴纳 15 元工本费，可在师生服务大厅自助补卡机补卡，也可前往师生服务大厅二楼人工窗口补办。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-005', '学校邮箱账号可以注销吗？', '可以注销，携带校园卡、身份证等证件前往信息化处办理注销即可。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-006', '自助补卡机是 24 小时开放吗？', '自助补卡机 24 小时开放', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-007', '校园卡被盗刷，消费记录在哪里能看？', '南航校园卡模块可查看消费记录；如需扣费明细，前往师生服务大厅二楼财务处查询扣费记录。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-008', '大四学生在外省正常学期实习，异地医疗费用可以走学校医保吗？', '异地就医可以报销，报销流程、材料可拨打校医院办公室电话 025-84895911 咨询。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-009', '如何申请软件著作权？', '打开南航信息化网站，进入师生服务大厅，搜索 “软件著作权”，即可查看登记审批、材料盖章等详细信息。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-010', '校园卡如何激活公交卡功能？', '对校园卡充值即可激活公交功能，可前往地铁站自助机器完成充值。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-011', '校园卡证件照如何更换？', '在师生服务大厅自助拍照机拍摄上传照片，补办校园卡即可完成照片更换。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-012', '启用新邮箱后，旧邮箱文件如何处理？', '系统迁移程序会自动迁移旧邮箱邮件，邮件数量大则迁移耗时较长；旧邮箱通讯录、文件中转站内容无法自动迁移，需要用户手动备份后导入新邮箱。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-013', '转诊校外医院做龈下刮治能否报销？', '需要咨询开具转诊单的老师确认报销资格。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-014', '校医院医疗报销流程？', '① 由校医院医生开具转诊单，前往指定挂钩医院就诊，无转诊单不予报销；'||CHAR(10)||'② 等待学校开放报销时段，到校医院四楼填写报销单、粘贴票据并上交至公费医疗办公室；'||CHAR(10)||'③ 医生审核后转交五楼会计室完成报销审核。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-015', '校医院是否可以输液挂盐水？', '校医院设有输液室，原则上支持输液，具体安排可咨询校医院工作人员。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-016', '补办校园卡输入密码含 X 提示格式错误，其他密码也无效如何解决？', '登录密码取字母前缀前的 6 位数字。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-017', '校园卡网费有余额，但 nuaa.portal、nuaa.wifi6 均提示欠费停机？', '需要进行账号复通，操作步骤：'||CHAR(10)||'手机浏览器访问 fuwu.nuaa.edu.cn → 点击右上角菜单栏 → 服务 → 账号复通。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-018', '校医院转诊单开具流程？', '普通门诊转诊：由校医院医师评估并签发转诊单，仅可前往指定挂钩医院就诊，无转诊单的校外就诊费用不予报销；'||CHAR(10)||'急诊：可免转诊，就诊后尽快联系校医院备案，方可走报销流程；'||CHAR(10)||'咨询专线：医保办 025-84895911。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-019', '爱心雨伞投放点位？', '师生服务大厅 5、6 号窗口、风雨操场值班台、巡天楼 2 楼值班室。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-020', '转专业', '拟同意名单 5 月公布，考核结果 8 月公布；不同类型转专业公示时间有差异，可咨询辅导员，或南航公众号回复关键词「转专业」查询详情。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-021', '跨校区借阅天目湖校区书籍', '进入「南京航空航天大学图书馆」公众号；'||CHAR(10)||'点击【资源】-【书刊查询】检索书籍；'||CHAR(10)||'书籍在其他校区时，点击【委托】，选定自身所在校区即可调借。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-022', '校园卡', '校园卡乘坐校外公交：在大厅旁智汇充卡机充值后可刷卡乘车；卡片丢失，乘车余额无法找回。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-023', '医保与就医报销', '1. 异地（非南京）门诊 '||CHAR(10)||' 普通校外门诊必须校医院开具转诊单；急诊可免转诊，但要尽快联系校医院；未经批准的校外门诊费用不予报销。'||CHAR(10)||'2. 异地住院 '||CHAR(10)||' 户籍地、南京三甲医院以外住院：提供户籍地医院盖章转诊说明；父母工作地住院提供居住证明。'||CHAR(10)||'3. 报销安排 '||CHAR(10)||' 报销办理时间：5 月 23 日 —25 日工作日，备好材料到校办理；查询方式：南航官微回复「医疗报销」。'||CHAR(10)||'4. 急诊就诊后需要第一时间和校医院联系报备。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-024', '南航粽子购买渠道', '1.i 南航平台→后勤服务→特色产品模块预订；'||CHAR(10)||'2.关注「南航食堂」公众号查看发售通知。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-025', '学生证充磁和注册盖章在哪里？', '学生证充磁是在师生服务大厅7号窗口进行，注册盖章是在辅导员处进行(注册盖章每学期应进行一次，丢失后补办的学生证应一并补盖），希望可以帮到你~', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-026', '学校最新的保研政策是怎样的？', '不同学院保研政策不同，相关政策已经发布，请你在教务网站查看相关政策或者咨询辅导员，希望可以帮助到你哦～', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-027', '入党需要多久呢？', '入党的相关事宜可以直接与导员沟通的。希望可以帮到你~', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-028', '绩点是如何计算的？', '绩点是评估学习成绩的一种方法，国内大部分高校通用的计算方法是：绩点=分数/10-5，学分绩点=学分*绩点=学分*（分数/10-5）。希望可以帮助到你~', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-029', '奖学金大概会在什么时候发放？', '不同的奖学金发放时间有所不同哦，具体可以参考下面的这张表，希望可以帮到你～'||CHAR(10)||'优秀学生奖学金 12月~1月'||CHAR(10)||'国家奖学金 11月~12月'||CHAR(10)||'国家助学金 春季学期按月发放，秋季学期12月份左右发放'||CHAR(10)||'学生通令奖 无奖金发放'||CHAR(10)||'特别奖学金 待通知'||CHAR(10)||'校长年度特别嘉奖 12月～1月'||CHAR(10)||'大学成就奖 5月'||CHAR(10)||'国防科技奖学金 11月~12月'||CHAR(10)||'国家励志奖学金 11月30日之前'||CHAR(10)||'校级特别奖学金 12月~1月'||CHAR(10)||'园丁励志奖学金 12月~1月', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-030', '如何知道竞赛报名时间和群?', '请积极关注南航教务处网站发布的最新资讯，各种竞赛相关消息都会在网站发布，也可以关注我们公众号的竞赛帮呀~希望我的回答可以帮助到你呀', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-031', '缴费相关?', '校园缴费（学费、住宿费）可以关注微信公众号南京航空航天大学智慧校园进行缴费，生活用费（校园网费、水电费）可以通过i南航app校园卡中缴费大厅进行缴费~希望可以帮到你~', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-032', '校园网账号复通如何操作?', '你可以登录http：//fuwu.nuaa.edu.cn网址，然后点击“服务”，“账号复通”，“立即复通”来复通校园网账户，希望可以帮到你~', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-033', '毕业生本科成绩单如何获取？', '本科毕业生成绩单需要到明故宫档案馆（图书馆一楼北侧）进行打印，希望可以帮到你~', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-034', '电子电路设计竞赛在哪里报名？', '电子电路设计竞赛报名时间大概在十一月初，具体报名时间和地点等其他相关事宜请关注“南航自动化科协”公众号，希望可以帮到你~', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-035', '通过宁聚计划落户集体户口的毕业生，户口首页和个人页在哪里看？', '户口办理有关问题可以通过拨打保卫处电话52118707进一步咨询呢，希望可以帮到你~', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-036', '怎样办理校园网？', '同学你好，首次使用校园网请在“南京航空航天大学智慧门户”微信公众号选择“应用广场”点击“校园网自助”菜单，登陆自助服务系统开通网络，希望可以帮到你~', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-037', '校园卡能乘坐南京市内公交地铁吗？如果可以的话还需要办什么手续呢？', '需要在微信公众号“南京市民卡''中进行市民卡和校园卡的nfc绑定，然后充值到南京市民卡中就可以啦！详细信息可以在i南航——校园卡——市民卡充值说明中了解哦！希望可以帮到你~', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-038', 'SX SF CG CZ是什么意思？', '前面两个意思分别是学术型硕士，非全日制硕士，后面两个是继续教育学院，希望可以帮到你~', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-039', '在校证明在哪里写?', '在校证明要联系本院教务员，教务员会告诉你相应的时间去办理的，希望可以帮到你~', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-040', '学校奇思妙想专利网上申请的具体网址在哪?', '可以登录科研院官网kyy.nuaa.edu.cn了解奇思妙想专利申报活动详情哦，希望可以帮助到你~', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-041', '如何登录校综合服务门户或VPN系统?', '可以登录i.nuaa.edu.cn访问智慧门户，可以登录v.nuaa.edu.cn查看VPN系统，希望可以帮到你~', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-042', '图书馆研讨室预约？', '现场预约：图书馆二楼大厅研讨室预约终端机预约；'||CHAR(10)||'网上预约：地址http://202.119.70.60/ClientWeb/xcus/ic2/Default.aspx；网上预约可提前 1 天进行，每天限预约一次；预约最短时间为 1 小时，最长时间为 4 小时；预约成功后请准时到达并使用研讨间，超过十五分钟视为自动取消该预约，并记违约一次，三次预约成功却不使用者视为恶意预约，系统自动取消预约人一个月的预约权限，希望可以帮到你~', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-043', '校园卡功能？', '校园卡功能如下：'||CHAR(10)||'一、商务消费类 主要包括餐厅就餐、校医院就医、开水房、机房、银联圈存、学生上网、自助打印等校内刷卡支付功能，实现“以卡代币”。'||CHAR(10)||'二、身份认证类 主要包括楼宇门禁、校园班车认证机、图书借阅、自助借还、多媒体教室管理等设备上进行身份验证功能，实现“以卡代证”。'||CHAR(10)||'三、混合应用类 新版校园卡支持全国200余座城市的公共交通乘坐，并享受相应优惠。希望可以帮助到你哦~', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-044', '勤工助学每个月最多30h吗?', '家庭经济困难学生助理原则上每月勤工助学时间不超过40h，非家庭经济困难学生助理原则上每月勤工助学时间不超过30h，希望可以帮到你！', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-045', '南京航空航天大学校学生会现在有哪些部门？', '南航学生会分为联络中心、文体中心、新媒体中心、权益服务中心、学业发展中心5个部门。希望可以帮到你~', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-046', '游泳馆开放时间？', '游泳馆开放时间为 周一至周五16:00-20:00，周六周日14:00-20:00，希望可以帮到你~', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-047', 'Wi-Fi6欠费了，缴费后怎么激活使用？', '进入校园网自助服务系统(http://net.nuaa.edu.cn)，点击账号复通，就可使用校园网了，希望可以帮助到你~', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-048', '如何查监控？', '如果你有特殊情况需要查监控，可以拨打电话监控中心(报警电话)52112110，希望可以帮助到你~', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-049', '如何查看所缴学费', '如需查看学年所缴学费，可进入缴费网站http://jiaofei.nuaa.edu.cn，也可搜索“南京航空航天大学智慧校园”公众号，点击【校园缴费】进入统一支付平台页面进行查看。希望可以帮助到你~', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-050', '研究生南航智慧门户如何换绑研究生账户?', '如需解绑本科信息，绑定研究生信息，需到信息化处办理，需要提供姓名、学号、身份证号等信息。明故宫位于综合楼7楼，将军路可在师生服务大厅办理。希望可以帮助到你~', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-051', '马拉松和光影竞赛等活动的时间？', '举办时间及结果公布时间都将会由学校统一发布通知，如未提前公布，请耐心等待。希望可以帮助到你~', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-052', '坐校车是刷校园卡吗？', '校园卡、微信、支付宝皆可。希望可以帮助到你~', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-053', '如何开具医保证明？', '医保证明可在“我的南京”APP中开具。进入我的南京→健康→医保服务，下划找到查询服务→居民医保参保缴费查询，点击查询本人，即可查看。希望可以帮助到你~', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-054', '我今年大一，为什么我开不了医保证明?', '大一新生的参保情况目前还未上报完毕，所以暂时无法查询医保证明，如果急需联系校医保办寻求帮助~医保办电话为84895911。希望可以帮助到你~', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-055', '校医院可以开验光单吗？', '校医院不可以开验光单，如有眼科问题，可开转诊单外出就诊。希望可以帮助到你~', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-056', '图书馆如何下载电子书？', '超星数字图书馆下载图书的方法：'||CHAR(10)||'（1）直接点击页面上的“下载”选项；'||CHAR(10)||'（2）查阅书目时，待超星浏览器打开所选图书后，再点击右键，在下拉菜单中选择“下载”。'||CHAR(10)||'南航教学参考书资源库下载方法：'||CHAR(10)||'查阅图书时，点击“借阅”，即把该书下载到本地机上；'||CHAR(10)||'更多资源到图书馆电子资源导航浏览，里面有更为详细的介绍(访问图书馆官网——首页——资源——电子资源导航)', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-057', '学分认定成功的网课没有出现在课表里面但是成绩单里有会影响学分获取吗？', '同学你好，只要成绩单上有课程成绩且没有挂科，不会影响学分获取的，希望可以帮你~', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-058', '志愿时长主要通过什么方式获取？', '同学，您好~您可以参加校级或院级的志愿活动，届时志愿汇APP上会显示您的志愿时长。校级和院级都有志愿者qq群聊，有关志愿活动问题可以寻求青协帮助，可以希望可以帮到您~', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-059', '怎么解决i南航的身份码刷不开宿舍楼门的问题（刷卡机显示卡未注册，以前是能够刷开的）？', '同学你好，新办理的校园卡有时会刷不开宿舍的门，可直接联系楼下宿舍阿姨、师生服务大厅18号窗口后勤集团或公寓服务中心（怡园17栋旁）进行办理，希望可以帮到你~', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-060', '校医院有公众号吗？如何获得医疗相关信息？', '同学你好，校医院没有公众号。但是有网站http://hospital.nuaa.edu.cn，现在校医院的信息一般会在企业号南京航空航天大学智慧门户医疗保健内通知。你还可以致电52116035获取更多信息，希望可以帮到你~', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-061', '怎么让南航图书馆开具SCI、EI、CPCI-S、CSSCI等检索证明？', '同学你好，进入南京航空航天大学图书馆官网，在右上角搜索查收查引 ，并填写“ 论文查收查引委托单”（附件），发送至jiansuo@nuaa.edu.cn；或者携带论文英文题名列表到图书馆109办公室办理。工作人员接到申请后，一般在 1-3 个工作日内出具检索结果。希望可以帮到你~', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-062', '学校给学生买了知网账号或有什么其他网站的会员吗？', '同学你好，数据库使用可以打开“南京航空航天大学图书馆”官网，在数据库列表中进行查询~希望可以帮到你~', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-063', '请问国家助学金是一次发完，还是一次只发一半，两学期发完？', '同学你好，国家助学金分批发放，秋季学期一次性发放50%，春季学期按月发放，直至发放完毕，希望可以帮到您~', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-064', '龙猫跑怎么申诉？', '同学你好，龙猫跑申述需微信公众号关注”龙猫校园体育平台“，点击个人中心-异常申述，选择申述项目，申述日期、时间和说明，并上传视频（app端异常录屏等），提交成功后可以在app的我的申述里查看申述状态，耐心等待审核即可。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-065', '咱们学校的大学生医保在外省可以用吗？', '同学你好，'||CHAR(10)||'（1）大学生异地实习及在户籍地（或生源地），因急诊住院可就近在当地就医，转往异地医院住院应先办理转外就医备案手续。'||CHAR(10)||'（2）参保学生携带经审核确认的《南京市基本医疗保险转外就医备案表》就近至市区医保经办机构异地就医窗口办理。转外就医备案有效期一年。备案后需办理省卡，并持省卡在异地刷卡结算。'||CHAR(10)||'（3）如未办理省卡，发生的住院费用先由个人垫付，出院后出院后凭病历复印件、住院发票、费用明细、出院小结等材料（自留复印件）、转外地医院需提供转外就医申请表等统一交至所在学校，由学校统一报区社保经办机构按规定办理审核报销。'||CHAR(10)||'（4）转外地医院住院未按规定办理转外就医申请，自行到异地就医发生的医疗费用由参保学生自理。'||CHAR(10)||'希望可以帮到你~', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-066', '12月校医院还能医疗报销吗？', '同学你好，以下是12月报销有关情况，希望可以帮到你~'||CHAR(10)||'将军路校医院一楼：12-13日8:00至12:00，以及14:00至17:00；'||CHAR(10)||'明故宫校区体育馆：15日8:00至12:00，以及14:00至17:00（可取住院支票）；'||CHAR(10)||'天目湖校区医院：19日9:00至12:00，以及13:00至16:00。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-067', '英语六级能学分替代多少学分？', '同学你好，英语六级480分以上能以90分代替一门两学分的英语课，希望能够帮到你~', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-068', '请问南航校园网怎么登知网并免费下载论文？', '同学你好，首先连接nuaa.wifi6等学校的校园网，然后直接登录知网（默认登录的是学校的账号），然后就可以下载论文了，或者在登录处选择校外登录，通过南京航空航天大学的登录口登录，希望可以帮助到你～', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-069', '四六级准考证在哪里可以打印？', '同学你好，四六级准考证可以在四六级报考官网进行下载后打印，希望可以帮到你~', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-070', '菜鸟驿站的快递忘记取了过了四十八小时会怎样？', '同学你好，为了保障快递循环投递，自提柜保存时间仅仅只有 48 小时，逾期菜鸟驿站将会拨打退件通知电话，若无法接通将会退回快递公司。希望可以帮到你~', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-071', 'i南航最新版本是多少？', '同学你好，i南航最新的版本是3.0版，新增了人脸识别服务、手机NFC服务等功能，希望能给你带来更好的使用体验，以下是下载网址 app.nuaa.edu.cn，打开后用手机扫描二维码即可下载，希望可以帮到你~', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-072', '如何查询期末成绩？', '同学你好，你可以通过登录教务系统查询期末考试成绩，微信公众号“南航教务处”会发布相关通知提醒你进行查询，希望可以帮到你。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-073', '退课是什么时间，为什么现在没法退课？', '同学你好，下一学期开课两周内可以选择退课，一般最多可以退两门，目前是无法退课的哦，希望可以帮到你。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-074', '校园网可以远程登录吗，如果不可以，那么校外如何访问图书馆呢？', '同学你好，校园网不可以远程登录,但同学可以通过使用统一身份认证登录VPN来访问图书馆'||CHAR(10)||'（1）PC端以浏览器为载体，使用统一身份认证登录智慧门户：i.nuaa.edu.cn，就可以访问图书馆资源及校内网站；或输入网址：v.nuaa.edu.cn，下载电脑客户端，安装完成后打开软件，输入地址：v.nuaa.edu.cn，用户名密码为学校统一身份认证账号，登录后输入资源地址直接访问即可'||CHAR(10)||'（2）手机端输入网址：v.nuaa.edu.cn，下载手机客户端，安装完成后，打开软件，输入地址：v.nuaa.edu.cn，用户名密码为学校统一身份认证账号，登录后输入资源地址直接访问即可，希望可以帮到你。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-075', '正版化软件在家里可以下载使用吗？', '同学你好，这是可以在家里下载使用的，学校建设了软件正版化服务平台：http://software.nuaa.edu.cn,为在校师生提供windows个人操作系统、Office软件套装等软件，希望可以帮到你。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-076', '校友卡怎么办理？', '同学你好，你可以搜索南京航空航天大学校友会微信公众号，点击下方的“服务大厅”进入小程序，再选择校友卡即可申领电子校友卡，希望能够帮到你。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-077', '请问怎么查询学生证还有没有火车票优惠次数呢？不知道需不需要充磁？', '同学你好，正常情况下一年充一次就行，剩余优惠次数可以在开学后来师生服务大厅7号窗口查询，希望可以帮到你。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-078', '请问学生证如果没有及时盖章注册有什么影响，和学籍注册没啥关系吧？', '同学你好，如果没有盖章，不影响学籍注册，盖章注册只是证明学生证有效，希望可以帮助到你。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-079', '邮箱毕业后还能用吗？', '同学你好，邮箱毕业后可以用的，目前时间没有限制，希望可以帮到你。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-080', '就业办的电话？', '同学你好，就业办的电话是：84892469，希望可以帮到你。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-081', '哪里能找到教务员电话？', '同学你好，你可以进入“南京航空航天大学学生服务”微信公众号，然后在下方的栏目中选择“牧生活”，再选择“常用电话”，找到“教务员”那一栏即可，不过请在工作时间与老师联系，希望可以帮到你。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-082', '校医院测甲流', '校医院目前是无法诊断甲流的，若有身体不适，可以去其他医院做检查，也可以查看微爷最近甲流推送了解更多关于甲流的信息。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-083', '校外人员进校手续', '校外人员进校须提前联系校内老师进行申请，审批通过后，可持身份证通过人脸识别门禁闸机，或凭报备信息驾乘车辆进入校园。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-084', '校友进校规定', '可以关注南京航空航天大学校友会公众号，在该公众号内可以办理电子校友卡，目前可以由班级负责人申请班级同学返校，如果有特殊情况，可以联系负责老师寻求帮助，老师的联系方式可以在南京航空航天大学校友会公众号查看。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-085', '必修课选上了能退课吗', '必修课开课前两周可退，但次年可能存在课程冲突等情况，建议按培养计划建议学期修读，无特殊情况尽量不退必修课。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-086', '选修游泳体育课有什么额外的要求吗', '选修游泳课后需在规定时间内前往校医院进行体检。选修游泳课的同学可直接通过学号领牌进入馆内，无需提前到值班室办理入馆手续。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-087', '毕业后还能正常返校参观吗', '可以。'||CHAR(10)||'毕业校友团体进校：参考南京航空航天大学官网-导航-校友-南航校友会-返校服务，在返校服务中查找进校审批入口及相关负责人联系方式。'||CHAR(10)||'毕业在南京就业的个人校友进校：关注南航校友会公众号，依次点击服务大厅-校友卡-个人返校提交申请，无需等待审批即可通过。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-088', '校园快递驿站什么时候关门', '菜鸟驿站取货架晚上19：00点关闭，自提柜24小时都可以取件。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-089', '游泳馆办卡时间为', '周一至周五14:00-17:00，周六至周日及节假日不办卡充值。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-090', '学期内怎么带领家人入校参观', '学生家长如果入校需先在i南航上申请，待导员审批通过后，家长可凭身份证通过人脸识别门禁。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-091', '暑假可以留校学习吗', '暑假留校学习是需要先联系辅导员的。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-092', '大学英语四六级什么时候报名参加', '江苏省四六级报名时间为4月27日到5月4日，具体以南航考点消息为主。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-093', '已毕业校友怎么补办“授予学位通知书”', '可将单位介绍信、需认证的证书、汇款凭证（邮政汇款30元到南京市秦淮区御道街29号南京航空航天大学档案馆）扫描件发送至邮箱nuaadag@nuaa.edu.cn，工作人员会在10个工作日内回复。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-094', '学校就业创业指导服务中心电话', '就业管理部52117780、就业市场部84892469、就业指导部52117668、创业指导部84892666。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-095', '请问为什么有些的科目总评超过5.0？如何提高科目的绩点？', '学校A课最终结课加0.5绩点，部分课程满绩为5.5；素质拓展学分也可提绩点；本学期学分替代工作已于4月12日结束，后续通知关注教务处官网。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-096', '请问修改乘车区间需要多长时间？', '周四之前办理一般下周一通知领取，周五办理一般下下周一通知领取。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-097', '请问游泳馆可以退回费用吗？', '无特殊原因无法退费，特殊情况请联系游泳馆体育老师。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-098', '请问将军路去天目湖校车是上车买票吗？票价多少？将军路到明故宫校车多少元一次？', '将军路至天目湖校车上车买票，票价40元；将军路到明故宫校车4元一次。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-099', '请问高铁优惠次数用完了怎么办？学生乘坐高铁资质核验是多久一次？', '每位同学一年仅有四次乘车优惠，每年会集中充磁增加次数；高铁学生资质核验每学年一次。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-100', '请问在i南航哪个入口申请家长进校呢？打开App后不知道在哪里申请？', '申请外来人员入校需提前联系辅导员申请，辅导员同意后可在i南航App首页搜索栏搜索“办事大厅-全部分类-（最底部）校外人员零星进出校申请办理”；若找不到此路径，可在办事大厅页面点击右下角“进入旧版”。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-101', '请问校友返校预约有没有次数限制？', '校友返校预约没有次数限制。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-102', '电动车邮寄报销规则', '4月15日前邮寄补贴300元；4月15日-4月29日补贴200元；4月29日-5月13日补贴100元；5月13日后不再提供集中邮寄服务和补贴。除邮寄至新疆、青海、西藏等地区需自付100多元邮费外，其他地区邮费全额补贴，补贴将转入学校发放的交通银行卡。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-103', '毕业校友忘记旧版南航邮箱密码怎么办', '可登录 http://mail.nuaa.edu.cn 点击忘记密码重置；无法解决可拨打南航信息化处电话52118710。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-104', '学生证核验', '使用电子客票的同学，乘车前应到车站自助售票窗口办理优惠资质绑定，学生票需每学年乘车前绑定一次，绑定成功后可直接刷身份证或二维码进站乘车。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-105', '学生证注册章', '每学期由辅导员统一收集加盖注册章，也可自行向辅导员提出加盖申请。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-106', '英语六级报考次数限制', '本科生英语六级报考次数限制为3次。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-107', '转专业要求', '具体转专业条件及要求、志愿填报、时间安排等通知，请查看教务处网站。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-108', '请问如何更改wifi6密码？', '同学你好，校园无线网账号是通过校内统一身份登录认证登录的，你可以通过“i南航"-我的-安全中心-修改密码进行统一身份认证密码修改，希望可以帮到你~', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-109', '请问一站式智慧面试亭如何预约？', '同学你好，该面试亭预约请参考链接https://s.r.sn.cn/VDFKW7，希望可以帮到你~', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-110', '请问如何办理车辆进校？', '同学你好，可以在校外人员访问里面，是否车辆进校中填入车牌号即可，希望可以帮到你～', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-111', '请问南航邮箱忘记密码怎么办？', '同学你好，可以登录浏览器：http://mail.nuaa.edu.cn然后点击忘记密码进行密码重置，如果不能解决问题，可以拨打南航信息化处电话：52118710，希望可以帮到你~', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-112', '请问如何查询哪些课程属于必修课程？', '同学你好，可以在教务系统上查看培养方案并且查看必修课程，希望可以帮到你~', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-113', '请问体育部电话是什么？', '同学你好呀，教务办公室电话为52117062，希望可以帮到你~', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-114', '请问游泳馆什么时间可以充卡？', '同学你好，游泳卡办理和次数充值可以在周一到周五14：00--17：00到游泳馆值班室二号口进行办理，希望可以帮到你~', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-115', '请问校医院能洗牙吗？', '同学你好，校医院口腔科是可以洗牙的，一次150元，但是不能报销，希望可以帮到你~', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-116', '请问校医院的工作时间是什么时候？', '同学你好，校医院的工作时间是8:00-12:00，14:00-17:30，急诊24小时有人值班，希望可以帮到你~', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-117', '请问如何办理户籍业务？', '同学你好，办理户籍业务日期为每周一5月15日、5月22日、5月29日，时间是13:00-16:00，地点在师生服务大厅1、2窗口。可以办理居民身份证新迁入或到期人员换发、遗失补办，临时居民身份证办理，港澳台居民居住证申领、换领、补领预约办理和边境通行证咨询，希望可以帮到你～', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-118', '请问如何办理出入境业务？', '同学你好，办理出入境业务日期为每周三5月17日、5月24日、5月31日，时间是13:00-16:00，地点在师生服务大厅1、2号窗口。办理的业务有出国境证件办理政策咨询，留学生签证、居留许可的政策咨询，留学生临时住宿登记政策咨询，适用简易程序的出入境案件政策咨询，希望可以帮到你~', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-119', '请问如何办理交管业务？', '同学你好，办理交管业务日期为每周五5月12日、5月19日、5月26日，时间是13:00-16:00，地点在师生服务大厅1、2号窗口。主要办理一般交通违法行为处理，希望可以帮到你~', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-120', '请问怎么查询我的户口现在在哪儿呢？', '同学你好，你可以在每周一13：00-16：00前往将军路师生服务大厅3号窗口公安政务服务窗口或者16号保卫处户籍科窗口查询，小微爷提醒同学记得带好身份证哦~希望可以帮到你~', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-121', '请问如何校内办理居住证呢？', '同学你好呀，学生居住证明由校园公寓服务中心开具。办理居住证需携带身份证、学生证和学生居住证明到警务室办理。希望可以帮到你~', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-122', '请问去天目湖校区有校车吗', '同学你好，三校区之间都是有校车的，你可以在i南航“校园班车”中看到具体的班次时间。希望可以帮到你~', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-123', '请问毕业季的跳蚤市场之类的活动要怎么参与呀？', '同学你好，毕业季的闲鱼市场、旧物捐赠、失物招领活动预计将在本月27日、28日进行，具体活动通知可以关注本公众号的后续推送，届时同学可以进行参与。希望可以帮到你~', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-124', '请问怎么预约羽毛球场地？', '同学你好，你可以登陆i南航进入预约服务版块，点击体育场馆，进入界面预约羽毛球场地，希望可以帮到你~', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-125', '请问我要怎么在南航勤工俭学呢？', '同学你好，学生学生助理学校QQ群是：941403703，你可以在群内了解详情。小微爷还要提醒一下，兼职不要耽误学习哦，学校关于勤工助学的规定请查询学生手册《南京航空航天大学学生勤工助学管理办法》，如果有其他问题也可以联系资助管理中心：52119832。希望可以帮到你~', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-126', '一个假期参加2个暑期社会实践团队之后怎么认定', '暑期社会实践可以加入两个团队，但不同学院认定规则可能不同，一个暑假内可能仅能认定一个，具体情况可询问辅导员。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-127', '本科生毕业典礼时间在什么时候', '今年本科生毕业典礼暂定于6月20号，具体时间请等待学校通知。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-128', '英语六级成绩学分代替具体怎么开展', '英语六级学分替代相关认定工作会发布在教务处网站，每学年两次，一般在每年五月和十一月开展，具体可前往教务处网站（aao.nuaa.edu.cn）搜索关键字“本科生大学英语课程学分认定及替代”了解详情。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-129', '学科重修该怎么办', '重修课程相关规定：部分课程班有名额限制，不及格需跟班重修的学生可在开学第一周优先申请，第二周再开放给刷绩点的学生申请；重修课程须与原修读记录中的课程规格完全一致，因教学计划变更导致原课程停开的，可联系学院教务员代为操作；刷绩点的及格课程重修最多可选2门或6学分（满足其一即可）。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-130', '选课人数扩容说明', '一般不扩容，请合理使用意愿值选课；必修课选满可联系学院教务员协助处理。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-131', '怎么查看自己的学费缴纳记录', '查看学费缴纳记录：微信进入“南京航空航天大学智慧校园”公众号，点击“校园缴费”功能，在“菜单”中选择“订单查询”即可。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-132', '教学评价网址', 'http://ev.nuaa.edu.cn，请及时完成教学评价。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-133', '学生证补办流程', '详见推送《滴~学生证补办流程有微调，请注意查收！》。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-134', '延长学年学生证使用说明', '学生证可继续使用，也能继续充磁。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-135', '各校区寄信地址及取信点', '天目湖校区地址为江苏省常州市溧阳市滨河东路29号。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-136', '学生证什么时候发放', '新生学生证一般第一学期末发放，老生补办可到师生服务大厅7、8号窗口办理。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-137', '校园卡充值后大概多久后会到账', '校园卡充值后正常1-2小时内到账。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-138', '从哪里能查询闲余空教室', '查询空教室可登录南航教务处网站，进入“课表”-“空教室查询”板块操作。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-139', '图书馆闭馆时桌面书籍处理方法', '图书馆晚上十点关门后清理桌上书籍，清理后的书籍存放于每层研讨间。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-140', '查询教师联系方式', '可登录教师个人主页：http://faculty.nuaa.edu.cn/获取相关信息。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-141', '失物招领处位置', '学生事务服务中心失物招领在东区天桥下师生服务大厅7、8号窗口，每栋教学楼一楼也设有失物招领处。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-142', '隐私号快递取件', '下载菜鸟APP导入快递信息查看自提柜编号，无法查询可联系快递员。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-143', '校内外卖柜查询', '外卖平台按所在位置填写校内地址，外卖员会送至对应外卖柜。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-144', '宿舍用电查询', 'i南航缴费大厅进入“学生公寓充电费”，输入寝室号查看当前电量，用量明细咨询宿舍管理员。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-145', '重修选课操作', '课程开课两周内登录南航教务系统，依次点击“选课”-“补退选申请”，选择重修课程提交申请，成功后3天内缴费，逾期视为放弃。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-146', '重修课程冲突处理', '联系任课老师，申请到同课程其他上课时间不同的平行班上课。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-147', '本部档案馆开放时间', '工作日8:00-12:00、14:00-17:30，法定节假日闭馆，周二16:00-17:30业务学习不对外开放。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-148', '宿舍刷脸系统人脸更换', '到师生服务大厅自助拍照更新。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-149', '南航各学院对应编号', '1航空学院、2能源与动力学院、3自动化学院、4电子信息工程学院/集成电路学院、5机电学院、6材料科学与技术学院、7民航学院、8数学学院、9经济与管理学院、10人文与社会科学学院、11艺术学院、12外国语学院、15航天学院、16计算机科学与技术学院/人工智能学院/软件学院、17马克思主义学院、18长空学院、19国际教育学院、20通用航空与飞行学院、21物理学院。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-150', '教材怎么购买', '教材可通过班级统一订购、开学后到菜鸟驿站教材科购买，或在确认版本后于线上购物软件自行购买。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-151', '朗读教室位置及开放时间', '天目湖校区为巡天楼T1513；开放时间为7:30-21:50（无课程安排时段）。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-152', '大创报销', '大创报销流程参考《南航教务处财务报销攻略》，链接http://aao.nuaa.edu.cn/2017/0112/c8243a171878/page.htm。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-153', '校车时刻表查询方式', '回复“校车”，或在“南航后勤”公众号微生活一栏查看最新版。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-154', '校园网开通及缴费方式', '首次使用需在“南京航空航天大学智慧门户”选择“E1.网络服务”，点击“业务办理”-“校园网自助服务”菜单登录自助服务系统开通；采用有线无线一体化计费，在多媒体机划款充值。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-155', '本科生图书馆借阅上限', '最多可同时借24本书。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-156', '专业选修课绩点规则', '属于选修课，不计入必修绩点。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-157', '计算思维导论重修规则', '理论课未通过但实验课通过的，无需重修实验课。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-158', '23级长空学院分流去向', '航空学院、能源与动力学院、机电学院、航天学院。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-159', '教师信息查询渠道', '登录http://faculty.nuaa.edu.cn/南京航空航天大学教师个人主页查询。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-160', '校内动火实验报备渠道', '拨打52118707联系保卫处报备。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-161', '社团招新信息查看渠道', '各社团公众号发布，后续有线下招新活动可留意。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-162', '宿舍门禁规则', '宿舍门禁启用时间23:00-次日6:00，夜间紧急情况出入需报辅导员确认，登记后可通行。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-163', '各校区大门开放时间', '路区西大门7:00-22:30；西区北门24小时开放；东门6:30-22:30；天目湖校区西北门24小时开放；明故宫校区西大门、东门24小时开放，小西门、北门6:00-22:30开放。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-164', '各宿舍楼区均设有红十字会衣物捐赠箱', '，可用于旧衣捐赠。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-165', '天目湖校区学院情况', '天目湖校区现有自动化学院、电子信息工程学院/集成电路学院、民航学院、计算机科学与技术学院/人工智能学院/软件学院、通用航空与飞行学院大一和大二学生。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-166', '勤工助学相关信息', '勤工助学相关信息可至大学生发展中心113室咨询，或拨打025-52117182咨询。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-167', '期末考试需要携带什么', '期中期末考试需携带校园卡核验个人信息。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-168', '哪些课程可以申请免修', '除政治、体育课外，其余课程均可申请免修，具体要求及流程见教务处发布的当年“课程免修工作的通知”。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-169', '专业排名查询', '向辅导员咨询，排名随课程出分动态变化。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-170', '失物招领', '师生服务大厅8号窗口；图书馆丢失可去二楼咨询台失物招领区，一周无人认领移交学生事务服务中心；微爷后台回复寻物提交信息匹配，有结果会通知。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-171', '借拐杖', '校医院可借，需带100元现金押金，一天一元。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-172', '校园卡补办密码', '身份证号码后六位；身份证最后一位是X则为身份证后七位去掉X。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-173', '期中成绩查询', '仅可通过询问老师得知。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-174', '普通话证书补办', '前往师生服务大厅教务处窗口（6号窗口）办理。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-175', '期末考试时间查询', '等老师通知或在教务处网站查询。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-176', '考试缓考申请', '先征得任课老师同意，登录教务系统申请，附件插入课程缓考申请表并附证明材料，经辅导员、教务员审核通过即完成；已缓考课程申请参加考试，填写已缓考课程考试申请单交学院教务老师。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-177', '寒假及后续招聘就业信息查询', '南京航空航天大学就业公众号服务栏咨询窗口自主查询。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-178', '校青协QQ群号', '704968368，群内发布志愿活动信息，报名即可参与志愿活动。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-179', '医保信息查询路径', '下载“我的南京”-“办事”-“健康医疗”-“医保服务”-“查询服务”-“居民医保参保缴费查询”-“查询本人”。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-180', '秋季优秀学生奖学金发放时间', '12月-次年1月。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-181', '本科生图书馆最大借阅量', '24本', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-182', '宿舍熄灯安排', '周五、周六晚不熄灯，周日到周四晚熄灯，期末复习周不熄灯', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-183', '体育课程“国防体育运动”内容', '围绕射击、射箭等项目展开，结课考核以体能训练及射击项目为主', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-184', '挂科与保研关系', '推免时课程完成培养计划要求，且无未通过的挂科科目，不影响保研', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-185', '英文版在读证明如何打印', '英文版在读证明需要找学院教务员老师或者前往本部档案馆开具。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-186', '事服电话号码是', '88790999', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-187', '南航宿舍卫生评定在哪查看？', '南航宿舍卫生评定在i南航上【后勤服务】-【公寓服务】-【卫生分数】-【宿舍成绩】进行查看。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-188', '作息时间表在哪查看？', '可以在微信公众号【航小务】-【移动教务】-【作息时间】查看，公众号还支持查看课表、考试安排、空闲教室查询等功能。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-189', '冻结校园卡问题', '根据《南京航空航天大学校园卡管理办法》第七章，第二十五条如因停电、断网等技术原因造成透支，学校有权向用户追索透支款项，可冻结校园卡的使用直至用户清偿透支款项或第八章，第二十八条校园卡仅限用户本人使用，不得出租、转让、抵押，否则将冻结该校园卡账户，或予以销户。同学可能是有透支校园卡或转借校园卡行为，可以前往财务处进行处理。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-190', '班级团关系转出', '如果是需要转出高中团支部，可以联系高中班级团支书；如果是需要转出目前所在大学团支部，可以联系班级团支书或向辅导员咨询。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-191', '医保待遇', '学生医保待遇享受期从次年的 1 月 1 日起至次年的 12 月 31 日为一个年度医疗保障期。新参保同学医保赠送参保当年9月1日~12月31日的医保待遇，在税务到账之前就医可先行现金自费垫付，待年底12月份进行线下零星报销，请同学们保留好发票及费用明细。税务到账后（学校会通知）必须刷卡（电子医保凭证）就医。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-192', '饮水机', '天目湖校区宿舍内的饮水机需要收费，教学楼内免费提供。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-193', '党费在哪缴纳？', '党费可以在zg.nuaa.edu.cn网站缴纳，也可以通过微信南京航空航天大学智慧门户进行缴费。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-194', '学校赛事', '学校的部分赛事会在教务网站上发布，各个承办赛事的学院也会发布相关赛事通知，除此之外，学校举办的校赛和相关竞赛一般会在学院的通知群里进行通知，学科类竞赛（如高数竞赛、部分地区大学生物理竞赛、全国大学生英语竞赛等）也会由相应学科的任课教师通知，可以多多关注教务网站消息和学院公众号推文，或者咨询你的任课教师或辅导员来了解未来的竞赛资讯。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-195', '国家助学金', '国家助学金一般在每年10 月下旬到11月开始受理申请，递交《国家助学金申请表》，当年 11 月评审完毕，具体情况可以咨询辅导员。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-196', '校园卡挂失后失效', '挂失过的校园卡会自动失效，没有挂失则不会', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-197', '怎么查看志愿时长', '下载“志愿汇”app后即可查询自己的志愿时长。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-198', '体测时间', '体测时间一般是在11月末12月初，具体时间需要等体育老师通知。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-199', '西服礼服可以在哪里租赁', '天目湖校区的同学可以前往事服爱心空间站进行西装租借。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-200', '学工号手机号码更换', '学工号绑定的手机号码更换可以进入统一身份认证个人中心，侧边栏“设置账号”-“手机号绑定”-“更换”，输入手机号及验证码进行更换，以下是身份认证个人中心的网址，https//authserver.nuaa.edu.cn/authserver', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-201', '怎么借用公共实验室设备', '借用公共实验室设备需要提前向实验室管理科负责老师说明具体情况，联系电话025-84892765', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-202', '电脑可以在哪里维修', '天目湖校区可以到b3华联超市对面维修电脑', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-203', '寝室灯坏了怎么报修', '寝室灯报修可以联系楼层宿管阿姨，你也可以在i南航的后勤-报修服务-水电报修里面登记。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-204', '常用电话怎么查询', '常用电话可以在南京航空航天大学学生服务公众号消息发送界面下方的“牧|生活”中查询。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-205', '怎么申请退课', '课程开课两周内登录教务系统，然后点击选课中的补退选申请，点击已选课程（退选/调班），操作退选就可以了（必修课一般是调班，退选请慎重），若开课已超过两周，需要询问学院教务员解决，正常情况下每学期限退课两门。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-206', '校园网最多同时连接几个设备', '校园网最多支持三个设备同时连接。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-207', '宿舍断电原因', '宿舍断电可先在i南航上查看所在宿舍电费情况，如果是宿舍欠费缴费即可，如果宿舍电费充足，可拨打公寓服务中心办公室电话88970618。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-208', '学校网络问题', '学校网络问题可以向信息化处投诉的哦（电话84890123）。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-209', '学业警示', '学期学业所差学分大于等于14且小于20 ；学业严重警示（延长学年）：学年学业所差学分大于等于20，或毕业年级学生在毕业学期未取得专业培养方案规定的总学分数，学业所差学分大于等于14。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-210', '专业大类流', '专业的大类流类别可以登录南航教务系统查看培养计划或与辅导员联系粉圈。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-211', '大创实验资金', '大创的实验资金一般会在初期评定之后下批。不同学院或许有所不同。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-212', '学校统一实习怎么开实习证明', '学校统一实习可以联系组织实习负责人开实习证明。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-213', '六级缺考', '六级缺考的话，有正当理由缺考的下次是还能够报名的，但是需要和辅导员说明，并且下次考试需要签字。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-214', '教务处窗口电话', '教务处窗口电话为52118171。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-215', '往年考试真题', '可以通过关注学业与发展支持中心公众号后，发送各课程名称获取往年考试真题。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-216', '大一申请了家庭经济困难认定，大二还需要重新申请吗', '大一申请了家庭经济困难认定，大二需要重新申请，具体要等待导员通知或者主动咨询，或者关注南航资助管理中心公众号获取具体信息。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-217', '综测', '综测与保研评奖评优有关，具体事项可咨询辅导员。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-218', '四六级耳机', '关于四六级听力耳机和考试相关的事项可以前往我校学支的微信公众号上查看，也可以看往年的四六级通知详情。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-219', '校园网时常不稳定', '校园网时常不稳定属正常现象，可能为后台网络维修等原因导致，一般过段时间方可稳定，如有更多疑问可以前往师生服务大厅 17 号窗口信息化处咨询。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-220', '哪里可以抽血化验', '南航校医院可以做抽血化验。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-221', '南航智慧学工系统', '南航智慧学工系统已经正式上线投入使用，有以下两种登录方式①登录网址: xg.nuaa.edu.cn使用统一身份认证登录。②手机端除使用网址外,也可在i南航上依次点击“更多应用——-校园——南航学工”进入系统。'||CHAR(10)||'注意：需要使用旧的奥蓝系统而又忘记密码的同学,若为本科生请联系辅导员老师重置,若为研究生请联系研究生院。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-222', '本科生请假', '本科生请假流程更新 （2021.10 ）为简化请假手续，同步请假数据至课堂考勤系统，面向全体本科生启用办事大厅“本科生请假申请”流程'||CHAR(10)||'1、电脑端：https://ehall.nuaa.edu.cn2、手机端：（1）微信企业号：南京航空航天大学智慧门户-网上办事-网办大厅-本科生服务-本科生请假申请 （2）i·南航-办事大厅-本科生服务-本科生请假申请'||CHAR(10)||'注：未经办事大厅请假的课程将产生旷课数据。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-223', '志愿时长要求', '每学期志愿时长是没有强制要求的，志愿时长在每学年综测分数评定、国家奖学金申请以及入党等环节都有用到。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-224', '常用电话怎么查看', '常用电话可以前往微信公众号“南京航空航天大学学生服务”，点击“牧生活”，进入“常用电话”查看。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-225', '校医院办公室联系方式', '天目湖校区校医院的办公室联系方式是0519-88970188。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-226', '平均绩点学分怎么计算', '平均学分绩点是你的课程绩点乘以相应学分求和后除以你的总学分得到的。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-227', '怎么进行场馆预约', 'i南航搜索天目湖校区“一站式”学生社区（关键词搜索天目湖应该可以跳出来），点击进入，点击场馆预约，自行翻找或搜索场馆名字。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-228', '湖区学生事务', '可以添加湖区小飞侠QQ号1872750049，或关注微信公众号“南航天目湖校区学生服务”，湖区事服将为你解答各类湖区学生事务。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-229', '教材电子版在哪里查找', '教材电子版可通过智慧门户进入“图书资源”条目查找，或进入南京航空航天大学图书馆官网后，点击“资源”-“电子资源导航”-“中文数据库”-“馆藏中文电子图书数据库”进一步了解。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-230', '课程回放', '飞天云课堂可以在点播栏选择高级搜索，之后查询相关学期，可以查询到以往已选课程的回放，', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-231', '云课堂密码', '云课堂密码是nuaa加上学号后六位，如nuaa413114', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-232', '校医保办的电话', '校医保办的电话是02584895911，记得在白天上班时间再打。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-233', '课程缓考成绩', '课程缓考成绩包含平时分，且课程缓考成绩不作折算，为过程考核成绩＋缓考考试成绩。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-234', '财务处的微信公众号', '财务处的微信公众号是“南航计划财务部”。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-235', '领航团', '学校成立了百名学生书记校长领航团，如果有需求或建议可以向领航团 “微心愿” 公共邮箱nuaastuvoice@163.com发送邮件。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-236', '南航校徽下载', '南航校徽可以访问“南京航空航天大学视觉形象识别系统官网”，在网站的校徽与校名规范栏可以下载。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-237', '体育部官网', '体育部官网https//sport.nuaa.edu.cn/main.htm', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-238', '医保报销范围', '门诊统筹待遇 起付标准100/自然年度 支付比例：社区医疗机构/校医院60%，非社区医疗机构40% 年度限额：普通学生600元 高血压/糖尿病患者1100元 两病同时患1500元。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-239', '天目湖校区的邮政编码', '天目湖校区的邮政编码是213300', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-240', '电子录取通知书查询', '电子录取通知书仅大一新生可在微信 南航本科新生电子录取通知书 小程序查询。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-241', '学位证和毕业证授予证明', '开学位证和毕业证授予证明可进入南航档案馆“学籍档案预 约”http//dagfy.nuaa.edu.cn/，根据提示填写信息，选择所需办理的相关材料后，提交订单，并选择自取或邮寄哦。（首次登录预约系统需先注册）', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-242', '空白大学物理实验报告单怎么打印', '空白大学物理实验报告单可以在微信公众号“南京航空航天大学物理实验中心”的选课系统中你已经选好的实验那里下载电子稿，然后找学校的自助打印机打印。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-243', '南航物理实验答题分数', '南航物理实验的按键——答题（），（）里面的数字就是你的答题分数，满分20分。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-244', 'QQ官方群号', '南航官方兼职群1：808944438南航官方兼职群2：1140231583南航官方兼职群3：941403703南航官方兼职群4：755654350南航官方兼职群5：869385262南航天目湖官方兼职群：926684141南航天目湖官方兼职群1：476162061另：南航学生助理学校QQ：2843295991', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-245', '缺考', '根据《本科生手册》规定，缺考课程考核成绩以零分计，不予补考，应重修。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-246', '新生报到需要注意什么?', '须持录取通知书和有关证件，按规定日期到校办理入学手续。学校在报到时对新生入学资格进行初步审查，审查合格办理入学手续，予以注册学籍。经审查发现录取通知、考生信息等证明材料与本人实际情况不符，或有违反国家招生考试规定情形的，取消入学资格。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-247', '不能按时报到怎么办?', '因故不能按期入学的，应提供相关证明，事先向学校请假，获批准可暂缓入学，最长期限为一个月。未经请假或虽请假但逾期的(不可抗力除外)，视为放弃入学资格。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-248', '可以申请保留入学资格吗?', '可以。因特殊困难不能入学的，可书面申请保留入学资格一年。应征入伍的新生，须提供相关证明，保留入学资格至退役后2年。保留入学资格期间不具有学籍，期满前须申请入学，审查不合格则取消入学资格。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-249', '入学后会进行复查吗?', '会。新生入学后三个月内，学校将进行入学复查，主要检查:1.录取手续及程序是否合乎国家招生规定;2.录取资格是否真实、合乎规定;3.本人及身份证明与录取通知、考生档案是否一致;4.身心健康状况是否符合报考专业体检要求;5.艺术、体育等特殊类型录取学生的专业水平是否符合要求。复查中发现弄虚作假、徇私舞弊的，取消学籍;情节严重移交有关部门处理。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-250', '每学期如何注册?', '每学期开学时，按规定缴纳有关费用后，持缴费凭证、学生证到所在学院办公室办理注册。不能如期注册的，应事先办理暂缓注册手续。未按学校规定缴纳费用或不符合注册条件的，不予注册。家庭经济困难学生可申请助学贷款或其他资助，办理相关手续后可注册。绿色通道:对被录取入学、经济困难的新生，一律先办理入学手续，缓交学费，再根据核实后的情况分别采取不同办法予以资助。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-251', '校园卡和银行卡怎么使用?', '新生会收到一张"太平洋"借记卡，需激活后方可使用。学费、住宿费等费用通过校园一卡通系统缴纳。贷款审批后，剩余款项通过校园一卡通系统转入学生校园银行账户。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-252', '本科几年毕业?', '本科学制为四年。学生在籍完成学业最短年限为三年，最长不超过六年(含休学、延长学习时间和退学试读时间)。经学校审定为休学创业的学生，学习年限可再延长，不超过2年。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-253', '可以换专业吗?', '可以。学生在学习期间对其他专业有兴趣和专长的，可以申请转专业。常规类型:面向一年级、二年级学生。特殊类型:面向二年级、三年级受到学业严重警示且未达到退学要求的学生，或不适合在现专业继续学习并经学院审定认可的学生。每学年组织一次，各专业每个年级接收常规类型转专业总名额原则上不超过原招生计划数的25%。学生在校期间，除特殊情形外，可不受专业限制转专业2次。不允许转专业的情形:入学未满一学期或本科四年级在读;受纪律处分且未解除;在休学期间;有转学经历;艺术类专业不得转入普通类专业;外语类保送生不得转入非外语类专业。休学创业或退役后复学的学生，因自身情况需要转专业的，同等条件下学校将优先考虑，且不占用转专业指标。转专业前应对申请转入专业进行全面了解，一经学院接收不得再撤销。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-254', '想修辅修专业或微专业怎么办?', '在修读主修专业的基础上，可申请修读学校设置的辅修专业或微专业。完成学习并达到相应要求的学生，学校发给辅修专业结业证书或微专业结业证书。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-255', '成绩好的课程可以申请免修吗?', '可以。前一学期平均学分绩点不低于3.0，或有特殊专长经学院认定和教师同意的学生，可申请免修考核。须在每学期开学后两周内提交自学材料，经任课教师同意、学院批准后方可参加免修考核。每学期免修一般不超过三门;重修的课程不得申请免修。不得免修:思想政治理论课、体育课和军训课、实验课、课程设计、毕业设计(论文)、实习等实践性环节。免修考核成绩须达到70分或中等，含有课程实践的课程还需完成实践环节且成绩合格。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-256', '不及格课程怎么处理?', '选修课程未取得学分:可重修本课程或改修其它课程。须在开学初规定时间内提出申请，逾期不予办理。重修课程与其他课程冲突时，经学院教务秘书认定、任课教师同意、学院批准，可准予不全部随堂听课，但须完成作业和实践环节并参加考试。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-257', '可以免听某些课程吗?', '自学能力较强、成绩优秀的学生，可在每学期开学注册时填报"课程免听申请表"，经任课教师同意、学院批准后准予免听或间隔听课。须完成作业、实践性环节和任课教师要求的考核。思想政治理论课、体育课不得免听。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-258', '可以去其他学校选课吗?', '可以申请跨校修读课程，或参加学校认可的开放式网络课程学习。修读的课程学分，经学校审核同意后，可予以认定。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-259', '大类招生可以分流吗?', '大类招生和培养学生可在本大类培养所涵盖的专业范围内申请分流。学院提前一年制订并公布专业分流方案，参照转专业办法开展大类培养专业分流工作。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-260', '考试作弊会有什么后果?', '考试违纪:视情节给予警告、严重警告、记过处分;该课程成绩无效(零分)，不予补考。考试作弊:给予留校察看以上处分;严重作弊者给予开除学籍处分。向他人出售考试试题或答案牟取利益的，给予开除学籍处分。违背学术诚信的，相应课程不予补考，可给予重修机会。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-261', '缺考或请假怎么办?', '因故不能参加考试须事先请假，经批准后方可缓考。课程考核缓考原则上每学期不超过一门，实践环节(实验课程、课程设计、实习等)不予缓考。学生应在考核前持有关证明，向所在学院提出申请，经学院批准后，方可缓考。缓考不及格不再安排补考，应重修。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-262', '什么情况下会被取消考核资格?', '有下列情形之一者，取消该课程考核资格，应予重修(成绩以零分计，不得补考):1.旷课累计达到三次及以上者;2.作业缺交四分之一及以上者(逾期一周不交者以缺交论);3.无故缺做实验或实验未达到要求者;4.实习、课程设计、毕业设计等旷课四分之一以上者。学生不得参加未按规定选课课程的考试，凡参加考试者成绩不予记载。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-263', '旷课会有什么后果?', '一学期累计旷课10-19学时:警告处分;一学期累计旷课20-29学时:严重警告处分;一学期累计旷课30-39学时:记过处分;一学期累计旷课40学时以上:留校察看处分。课堂教学按实际授课时间计;实习、课程设计、毕业设计期间及无故未按时报到者，每日按4学时计。一学期内受处分后，旷课学时重新累计。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-264', '什么情况下可以休学?', '经医院诊断，须治疗修养期占一学期三分之一以上的，须办理休学。因出国、创业等原因需暂停学业的，经学院同意可办理休学。一学期请假累计超过一个月，应休学一学期。每次休学最长期限为一年，休学期间须离校，不享受在校学习学生待遇。应征入伍的，保留学籍至退役后2年。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-265', '如何复学?', '应提前一周向所在学院申请复学。休学期满不能复学的，应提出延长申请，延长期不超过一年。须提交休学期间活动说明和体检证明(因病还需医院疾病康复证明)，经学校审核合格办理复学手续。复学时一般降级至同专业相应年级学习。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-266', '什么情况下会被退学?', '超过两周未注册且未履行暂缓注册手续;经指定医院诊断患有疾病或意外伤残不能继续学习;休学、保留学籍期满，超过两周未申请复学或复查不合格;未经批准连续两周或一学期累计一个月未参加学校规定的教学活动;在规定学习年限内未完成学业且未达到结业要求;学业所差学分≥30学分;延长学习期间取得学分数未达到个人学习计划学分的70%;第三次受到学业严重警示;符合延长学习时间条件但未在规定时间内申请。学生本人也可申请退学，经学校审核同意后办理手续。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-267', '学业警示是什么?', '学业所差学分≥14且<20:给予一次学业警示。学业所差学分≥20:给予一次学业严重警示。毕业学期末未取得总学分数且所差学分≥14:给予学业严重警示。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-268', '会被强制退学吗?有没有补救机会?', '因学业所差学分≥30或延长学习期间未达标而符合退学条件的学生，经个人申请、家长到校确认、学院审核、学校批准，可给予一次退学试读机会(同时记学业严重警示一次)，编入下一年级学习。退学试读期间须严格遵守规章制度，每学期取得学分数须达到个人学习计划学分数的70%，否则予以退学。在校期间只能申请一次退学试读。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-269', '不能毕业怎么办?', '学满一年及以上时间退学的，学校发给肄业证书。学习不满一年的、开除学籍的，学校发给写实性学习证明。在规定年限内未获得全部学分，所差学分<14的，予以结业，发给结业证书。结业学生可在结业后两年内申请课程换证重修或考核，补满所差学分后携结业证书回校申请换发毕业证书。结业学生在课程换证重修或考核过程中作弊的，成绩无效，以零分计;第二次作弊的，取消换证重修或考核资格。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-270', '怎样可以毕业?', '在规定的学习年限内，修满专业培养方案规定的全部课程，成绩合格，达到学校毕业要求。在校学习未满四年的学生，如提前完成培养方案规定内容并获得毕业所要求的学分，可申请提前毕业，经学院核实、教务处审定、报校长批准后准予提前毕业。学校于每年五月、十一月受理提前毕业申请。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-271', '怎样可以获得学士学位?', '热爱祖国，拥护中国共产党的领导，遵纪守法，品行端正;较好地掌握本门学科的基础理论、专门知识和基本技能;在规定的学习年限内修满专业培养方案规定的全部课程，成绩合格;平均学分绩点≥2.0。有作弊、抄袭、剽窃等违背学术诚信行为的，原则上不授予学士学位。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-272', '结业后还能拿学位吗?', '结业学生以及因未达到学位条件而未获得学士学位的毕业生，在离校后两年内回校重修课程，达到学士学位授予条件，可申请授予学士学位。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-273', '什么是素质能力测评?', '学校对本科生实行素质能力测评及评优评奖制度，测评结果作为参与年度评优评奖的主要依据。测评分为三项:1.专业学习评价:以平均学分绩点计算。2.基本素质评价:从责任意识、创新精神、国际视野、人文情怀四个方面进行评价，分优秀、良好、中等、合格四个等级。3.实践项目评价:包括党团建设、思想辨析、学干培养、学术建设、科创研修、实习实践、文化交流、身心发展等模块。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-274', '新生需要做什么素质拓展?', '全体本科新生需填写《南京航空航天大学素质能力自我评估量表》，了解自身素质能力发展现状。由辅导员指导填写《南京航空航天大学学生素质拓展"群星计划"立项表》。大二秋季学期初、大三秋季学期初分别进行中期考核。大三春季学期中开展成果报告单填写。这些材料将纳入学生档案，作为向用人单位、升学院校推荐学生的重要参考。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-275', '学费和住宿费怎么收取?', '学费、住宿费按学年收取，不得跨学年预收。实行学分制收费的，按学分收取学费，总额不得超过学年收费总额。具体收费标准在入学通知书中注明。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-276', '资助体系有哪些?', '学校资助工作按功能分为四类:保障性资助:国家助学贷款、国家助学金、社会类助学金、困难补助、学费减免、绿色通道等，帮助家庭经济困难学生解决学费、住宿费问题。激励性资助:国家奖学金、国家励志奖学金、校级各类奖学金等，激励学生勤奋学习。引导性资助:中西部基层就业学费补偿、应征入伍学费补偿和贷款代偿、退役士兵教育资助等，引导学生到基层和部队建功立业。强能性资助:勤工助学、专项技能竞赛等，帮助学生提升综合素质能力。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-277', '可以申请国家助学金吗?', '可以。国家助学金用于资助家庭经济困难学生的生活费用。资助标准:平均每生每年3700元，具体在每生每年2500-5000元范围内确定，分三档:一般困难:2500-3000元/年;困难:3500-4000元/年;特别困难:4500-5000元/年。全日制在校退役士兵学生全部享受本科国家助学金。获得国家奖学金的学生可同时申请国家助学金，但不能同时获得国家励志奖学金。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-278', '可以减免学费吗?', '对于家庭经济困难的全日制本科生，学校按省人民政府有关规定酌情减收或免收学费。主要面向孤儿、残疾学生、军烈属子女、享受低保政策或原建档立卡家庭等特殊困难学生。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-279', '奖学金有哪些?', '国家奖学金:10000元/人，奖励二年级以上(含)特别优秀的学生，成绩和综合素质测评均位于专业前10%(特殊情况可放宽至前30%)。国家励志奖学金:6000元/人，奖励二年级以上(含)品学兼优的家庭经济困难学生。优秀学生奖学金:一等奖2500元/人(专业前3%)、二等奖1500元/人(专业前5%)、三等奖1000元/人(专业前22%)。学业奖学金:一等奖500元/人、二等奖400元/人、三等奖300元/人，覆盖专业前60%。还有校长特别嘉奖(最高10000元/人)、大学成就奖、园丁励志奖学金、特别奖学金、国防科技奖学金等多种校级奖学金。评定遵循公开、公平、公正原则，每学年9月启动非毕业班评优，4月启动毕业班评优。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-280', '国家助学贷款怎么申请?', '分校园地国家助学贷款和生源地信用助学贷款两种，只能选择其中一种申请，不得重复。贷款额度:本科生每人每年最高不超过20000元。贷款期限:学制加15年，最长不超过22年。利率:在校期间的贷款利息全部由国家财政补贴，毕业后的本息由学生本人支付。还本宽限期:5年。办理无需担保或抵押。申请时需提交相关证明材料，经学校资助管理中心审核、银行审批后发放。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-281', '什么是家庭经济困难学生认定?', '认定工作每学年进行一次。新生收到录取通知书时，同时寄送《家庭经济困难学生认定申请表》。学生登录江苏省学生资助申请平台网上填报信息，在线进行困难程度量化评估。认定分为三级:特别困难、困难、一般困难。原建档立卡贫困家庭学生、低保家庭学生、特困供养学生、孤残学生、烈士子女等需附相关证明材料。认定评议小组进行民主评议，不能让学生当众诉苦、互相比困。结果公示5个工作日，有异议可向学院或学校提出。学校每年开学时对全部家庭经济困难学生进行资格复查。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-282', '可以在校内组织或参加社团吗?', '可以。学生可以在校内成立、参加学生社团。学生成立社团，应当按学校有关规定提出书面申请，报学校批准，并实行登记和年检制度。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-283', '校园内有哪些行为是被禁止的?', '酗酒、打架斗殴、赌博、吸毒;传播、复制、贩卖非法书刊和音像制品;参与非法传销、邪教、封建迷信活动;在校内进行宗教活动;登录非法网站、传播非法信息;攻击、侵入他人计算机和网络系统;偷窃、诈骗、故意损坏公私财物;伪造证件、成绩单;考试作弊、学术不端;在公共场合观看淫秽物品或浏览色情网站;私自留宿校外人员、留宿异性、未经许可夜不归宿或校外租房等。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-284', '违反校规会有什么处分?', '纪律处分分为五种:警告、严重警告、记过、留校察看、开除学籍。处分本着证据充分、依据明确、定性准确、程序正当、处分适当的原则。受处分期间的限制:不得参与评优评奖;不得申请各类困难补助;担任学生干部者，免去相应职务。留校察看期为一年，确有悔改进步者可按期或提前解除处分(提前须察看期不少于六个月)。从轻或免于处分的情形:主动交待违纪事实、有检举立功表现、被胁迫或诱骗并能主动揭发。加重处分的情形:拒不承认错误、威胁报复检举人/证人/工作人员、在校期间已受过处分再次违纪。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-285', '对处分决定有异议怎么办?', '在接到学校处分决定书之日起10日内，向学校学生申诉处理委员会提出书面申诉。申诉处理委员会由不少于九人的委员组成(含校领导、职能部门负责人、法律顾问、教师代表、学生代表等)，决议需三分之二以上通过。申诉处理委员会在接到书面申诉之日起15日内作出复查结论，最长可延长15日。可采取书面审查或召开听证会的方式处理。对复查决定仍有异议的，在接到复查决定书之日起15日内，可向江苏省教育厅提出书面申诉。申诉期间，委员会认为必要时可要求暂缓执行有关决定。处分决定书直接送达有困难的，以在学校网站发布公告的形式送达，自公布之日起经30日，视为送达。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-286', '学校有保障学生安全的措施吗?', '有安全教育、安全管理相关规定，以及学生伤害事故处理相关规定。安全教育以预防为主，包括防盗、防火、防特、防病、防事故等方面的教育。学校注重心理疏导，帮助学生克服因各种原因造成的心理障碍。学生须遵守学校关于住宿管理、实验室安全、消防安全等规定。私自使用电器、高空抛物等违规行为将受到相应处分。发生重大安全事故的，学校迅速采取措施进行抢救，保护现场，并协同地方有关部门妥善处理。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-287', '可以应征入伍吗?有哪些政策?', '可以。学生应征入伍可保留学籍至退役后2年。学费补偿/贷款代偿:本科生每生每年最高不超过20000元，补偿资金优先用于偿还国家助学贷款。退役后复学的学生，学费减免年限接续完成规定的剩余修业年限。退役后考入高校的新生，规定的基本修业年限即为学费减免年限。退役士兵教育资助:自2019年秋季学期起，对自主就业退役士兵学生提供学费资助，本科生最高不超过年人均20000元，生活费及其他奖助学金按国家现行高校学生资助政策执行。因故意隐瞒病史、弄虚作假、违法犯罪等行为造成退兵的，取消资助资格;非正常退役学生的资助资格认定由省级征兵办公室会同教育行政部门确定。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-288', '毕业后去基层就业有资助吗?', '应届毕业生到中西部地区和艰苦边远地区基层单位就业、服务期在3年以上(含3年)的，学费由国家实行补偿，每人每年最高不超过20000元。采取分年度补偿代偿的办法，毕业后每年补偿代偿总额的1/3，3年完成。未满3年服务年限提前离开的，须申请取消代偿资格，未结清贷款部分需自行偿还。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-289', '本科生有几个校区?', '学校建有明故宫、将军路、天目湖三个校区和国际创新港。目前有本科专业67个、硕士一级学科授权点32个、博士一级学科授权点20个。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-290', '图书馆资源如何使用?', '学校图书馆收藏331.6万余件印刷型文献、183个中外文数据库、1452万余册电子型及数字型文献信息资源。图书馆为学生提供本馆资料检索和查询服务，不收费。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-291', '医保和保险是怎么安排的?', '新生报到后，经体检合格并参加南京市或溧阳市城镇居民基本医疗保险者，发放病历一本。该病历是个人的医疗健康档案，也是享受医保待遇报销的凭证，务必妥善保存。病历遗失须由个人申请，经所在院系证明盖章，携带手续费20元到校医院补办。学生患病凭本人病历可在三个校区医院门诊部挂号就诊，按规定比例自付一定数额医疗费。因病需转外就诊者，须由本校医生签发转诊单到指定的挂钩医院就诊;未经批准自行在外院就诊的，费用不予报销。寒暑假回家探亲，因病在当地公立医院门诊就诊，门诊医疗费实行限额报销:寒假限报10元，暑假限报20元。休学期间，门诊医疗费全年限报500元，超出部分自理。因病需住院者，可凭市民卡在医保定点医院办理住院手续，返校后提交相关材料申请医保报销。病历不得转借，凡转借一经发现，则给予当事人双方各当日医疗费10倍处罚。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-292', '可以参加勤工助学吗?', '可以。学校统一组织和管理勤工助学活动，学生助理学校具体负责招募、培训、考核等工作。薪酬标准:校内勤工助学薪酬为15元/小时(根据规定动态调整)。原则上所聘用学生上一学期有2门以上科目成绩不及格的，应适当限制其参加下学期的勤工助学工作。校外私自勤工助学行为不在学校管理范围内。勤工助学学生须先培训后上岗。年终考核优秀者，可申请勤工助学优秀员工(500元/年)和勤工助学明星员工(800元/年)荣誉称号。求职创业补贴:向残疾、低保家庭、原建档立卡家庭经济困难应届毕业生提供求职创业补贴。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-293', '学生在校期间享有哪些权利?', '参加教育教学计划安排的各项活动，使用教育教学设施、设备、图书资料;参加社会实践、志愿服务、勤工助学、文娱体育及科技文化创新等活动，获得就业创业指导和服务;申请奖学金、助学金及助学贷款;在思想品德、学业成绩等方面获得科学、公正评价;在校内组织、参加学生团体，以适当方式参与学校管理;对学校给予的处理或者处分有异议，向学校或教育行政部门提出申诉;法律、法规及学校章程规定的其他权利。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-294', '高水平运动员有什么特殊政策?', '高水平运动员学习期限可比普通本科生延长1-2年。课程考核成绩由课程原始成绩(50%)、运动训练成绩(20%)、体育竞赛成绩(30%)三部分构成。A类运动员(国家队/省队现役)可认定4学分，B类运动员体育竞赛认定3学分、运动训练认定2学分。运动员必修学分最多可替代24学分，选修学分最多可替代12学分。竞赛/训练与上课或考试冲突的，由体育部统一办理请假或缓考手续。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-295', '学生档案和户口如何处理?', '受开除学籍处分的学生，在接到处分决定书起一周内必须离开学校，其户口档案一律退回其家庭户籍所在地。学生奖励、处分材料真实完整地归入学校文书档案和本人档案。学生档案由学院负责管理，在校期间不向学生个人开放查阅。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-296', '国防科技奖学金是什么?', '国防科技奖学金由国家设立，用于鼓励优秀学生积极投身国防事业。奖励标准:每生每学年10000元，本科生享受奖学金年限不超过4年。申请条件:热爱祖国、拥护党的领导、有志于投身国防科技事业;遵守法律法规和校纪校规;诚实守信;学习勤奋刻苦，成绩优良。服务年限:毕业后应按照协议规定到用人单位就业，服务年限不得少于5年。违约责任:违约需退还已获得的全部国防科技奖学金，同时一次性缴纳与其已获得的国防科技奖学金总额相等的违约金。视为违约的情形包括:政治立场不坚定、违反国家法律、泄露国家秘密、受到严重警告以上处分、年度考核不合格、中途退学转专业、不能按期完成学业、不按规定就业等。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-297', '证书/证明书/成绩单怎么开具?', '毕业证书、学位证书遗失或损坏的，经本人申请，学校核实后可出具相应的证明书。证明书与原证书具有同等效力。成绩单是学生在校学习期间所有课程成绩的正式记录，是学生学业情况的重要证明文件。成绩单通常由教务处统一出具，可通过教务系统申请打印或前往教务处办理。成绩单一般用于出国留学、就业、考研等需要学业成绩证明的场合。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-298', '可以提前毕业吗?', '可以。在校学习未满四年的学生，如提前完成教育教学计划规定内容，获得毕业所要求的学分，可以申请提前毕业。学校于每年五月、十一月受理提前毕业申请。已受理提前毕业申请且具备毕业条件的学生，经学院核实、教务处审定、报校长批准，准予提前毕业。提前毕业的学生按实际修读学年数(以半年为计算单位)收取专业学费。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-299', '绩点如何计算', '平均学分绩点计算公式:平均学分绩点 =∑课程绩点×课程学分×权重系数÷∑课程学分', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-300', '补考绩点计算和正常考试的一样吗', '不一样,补考大于 80分的部分在计算绩点时需要折半', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-301', '有转专业的机会吗', '有的,大一、大二均有转专业的机会', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-302', '评优评奖什么时候开始啊', '非毕业班评优评奖工作于每年 9月份启动,毕业班于每年 4月份启动。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-303', '学校缴费在哪里缴', '学校目前不再采用银行代扣的缴费方式,推荐使用手机或电脑登录学校统一支付平台缴费。登录用户名为学号,密码为身份证号后六位(含 X的须大写)。'||CHAR(10)||'(1)打开手机微信或支付宝，扫描二维码，登录学校统一支付平台，输入学号和密码,选择缴费项目进行缴费。'||CHAR(10)||'(2)打开手机微信，搜索“南京航空航天大学智慧校园”公众号,点击校园缴费,登录学校统一支付平台,输入学号和密码,选择缴费项目进行缴费。'||CHAR(10)||'(3)电脑浏览器输入链接  http://jiaofei.nuaa.edu.cn,登录学校统一支付平台,输入学号和密码,选择缴费项目进行缴费。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-304', '宿舍内有哪些不能用的东西', '公寓楼内严禁在室内私拉、乱接电线、(接线板串联使用),严禁做电工电子试验,严禁在公寓内存放和违章使用伪劣电器、大功率、有电加热或制冷功能或者金属材质导热的电器，包括热得快、电热杯、电炉、电饭煲、电熨斗、电水壶、电热毯、取暖器、电冰箱、洗衣机、烘鞋器、电干衣机、微波炉、电烙铁、电动车、充电电瓶(蓄电池)、航模电池和户外电源等、食品电加工设备和鱼缸的电增氧泵、电热泵等附属电设备;严禁使用有安全隐患的充电宝(超过可循环使用年限或出现变色、变形、漏液、易发烫但仍能充进电),以防发生短路、触电、火灾等事故。确保安全使用各类电源、用电设备(须检查插头与插座是否接触松动或接触不良,充电线、数据线如有破损立即停止使用。接线板、充电中的手机等设备严禁放置在或靠近床褥、衣服等易燃物)', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-305', '可以申请不住校吗', '可以，但是要满足以下条件之一:(1)因病确需住在校外治疗、调养，且有家长陪护的学生(需有医院证明)。(2)家庭所在地为南京市或在南京有主要亲属的三、四年级学生。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-306', '可以在校园里骑电动车/自行车吗', '天目湖校区不允许学生骑电动车/自行车等非机动车入校。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-307', '什么情况下会被取消考试资格', '有下列情形之一者,取消该课程考核资格,应予重修。'||CHAR(10)||'(1)旷课累计达到三次及以上者;'||CHAR(10)||'(2)作业缺交四分之一及以上者(按教师规定的时间,逾期一周者,以缺交作业论);'||CHAR(10)||'(3)无故缺做实验或实验未达到要求者;'||CHAR(10)||'(4)实习、课程设计、毕业设计等旷课四分之一以上者。'||CHAR(10)||'被取消考核资格的课程,成绩以零分计,不得补考。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-308', '体育课成绩和其他科目的计算方式一样吗', '考试成绩一、二年级采用百分制，三、四年级采用五级分制。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-309', '学校对社会实践有要求吗?', '学生在校期间，必须参加每年一次的暑期社会实践活动和寒假社会实践活动，且开展活动时间每个学年累计不得少于一周。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-310', '关于户籍问题可以向谁咨询?', '天目湖校区户籍服务地址:综合服务楼109室电话:0519-88970089', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-311', '哪些情况下可以申请家庭困难认定?', '(一)学生属于扶贫部门认定的原建档立卡贫困家庭子女，民政部门认定的最低生活保障家庭子女、特困救助供养人员、孤儿、困境儿童、享受国家定期抚恤补助的优抚对象子女、因公牺牲警察子女、残联认定的残疾人及残疾人子女、工会组织认定的特困职工家庭子女等。'||CHAR(10)||'(二)学生家庭遭受重大自然灾害、重大突发意外事件。'||CHAR(10)||'(三)学生户籍所在地经济发展水平、城乡居民最低生活保障标准，学校所在地的物价水平和学校收费标准。'||CHAR(10)||'(四)学生家庭收入和资产、负债状况。'||CHAR(10)||'(五)学生家庭赡养老人和抚养其他就学子女等负担情况，劳动力文化和职业、收入情况，家庭成员健康状况。'||CHAR(10)||'(六)学生消费的金额、结构等合理性。'||CHAR(10)||'(七)学生本人健康状况等。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-312', '图书馆的书籍资料最多可以借阅多少天?', '一次最多可以借阅30天，本科生可以续借一次。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-313', '成绩怎么评定', '课程考核成绩采用百分制或五级分制(优秀、良好、中等、及格、不及格)评定记分，原则上核心主干课程采用百分制。百分制对应五级分制:90-100分:优秀;80-89分:良好;70-79分:中等;60-69分:及格;0-59分:不及格。同时采用课程绩点评价课程学习质量，采用平均学分绩点综合评价专业学习质量。平均学分绩点计算公式:平均学分绩点=∑(课程绩点x课程学分)÷∑课程学分，保留一位小数。过程考核成绩(作业、测验、期中考核、实验、考勤等)由任课教师在课程开始时公布占比，与结束考核成绩综合评定。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-314', '校内有哪些常用的网站?', '南京航空航天大学主页http://nuaa.edu.cn'||CHAR(10)||'教务处网站: http://aao.nuaa.edu.cn'||CHAR(10)||'教学评估网站: http://nwp.nuaa.edu.cn'||CHAR(10)||'学生工作处网站: http://xsc.nuaa.edu.cn'||CHAR(10)||'学生工作处招生网站: http://zs.nuaa.edu.cn'||CHAR(10)||'学生工作处就业网站: http://nuaa.91job.org.cn'||CHAR(10)||'学生管理信息系统: http://xg.nuaa.edu.cn'||CHAR(10)||'校团委网站: http://youth.nuaa.edu.cn'||CHAR(10)||'研究生院网站: http://www.graduate.nuaa.edu.cn'||CHAR(10)||'信息化处网站: http://xxhc.nuaa.edu.cn'||CHAR(10)||'综合服务门户: http://i.nuaa.edu.cn'||CHAR(10)||'教师个人主页: http://faculty.nuaa.edu.cn'||CHAR(10)||'天目湖校区网站: http://tmhxq.nuaa.edu.cn', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-315', '体育课因为身体原因可以不参加吗?', '因伤病较长时间不能参加体育课的学生,由本人提出申请,校医院相关科室核准，报体育部批准，可参加康复课的学习。康复课期末成绩百分制最高不超69分，五级分制为及格和不及格。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-316', '请问有班车时间表吗', '有班车时间表，可以在南京航空航天大学学生服务公众号查询。i南航里面搜索“校园班车”，可以查看校园班车时刻表，选择想要去的校区的栏目，可以查看将军路校区到明故宫校区和天目湖校区的班车。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-0317', '南京航空航天大学2026级新生报到时间是什么时候？', '2026年8月29日、8月30日。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-0318', '南航天目湖校区报到地点是什么？', '江苏省溧阳市滨河东路29号。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-0319', '学校哪些站点设置了新生接待站？', '南京火车站、南京南站、高铁溧阳站。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-0320', '新生凭什么证件可以入校？', '录取通知书。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-0321', '迎新系统什么时候开放？网址是什么？', '2026年8月25日开放，网址yx.nuaa.edu.cn。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-0322', '迎新系统登录账号和初始密码是什么？', '用户名为学生考生号，港澳台学生为身份证号码后六位；初始密码为St+身份证号码后六位。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-0323', '迎新系统里面可以办理哪些业务？', '可进行新生信息预报到，办理户口迁移信息登记、宿舍用品订购、家庭经济困难学生绿色通道等工作，还可以查询个人班级、学号、宿舍分配、缴费标准、报到地点等信息。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-0324', '《走近南京》《走进南航》课程是什么，有多少学分？', '是面向新生开设的通识核心课，入学前在超星学习通平台完成学习，可以认定1学分。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-0325', '2026级新生英语水平测试什么时候开展？', '入校后统一参加。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-0326', '新生报到志愿者招募信息在哪里查看，什么时候发布？', '关注“青年南航”微信公众平台，2026年8月15日后发布相关信息。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-0327', '学籍电子照片上传时间段是什么？', '2026年8月25日‑9月10日。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-0328', '学籍电子照片有什么要求？', '蓝色背景免冠正面半身照，背景颜色均匀无渐变；大小200K‑900K，JPG格式；穿白色上衣，头发不遮挡眉毛和脸颊，长发全部放在肩膀后方；照片清晰真实，不做美颜等图像处理。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-0329', '上传学籍电子照片有哪两种方式？', 'a.教务系统上传，网址aao.nuaa.edu.cn，统一身份认证登录，点击学籍信息‑个人信息变更‑照片上传；b.微信二维码采集，扫码后统一身份认证登录，阅读注意事项后上传、裁剪、提交照片。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-0330', '学籍照片上传遇到问题怎么咨询？', '加入QQ群105637599：2026新生图采QQ群咨询技术人员。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-0331', '报到需要携带哪些证件材料？', '1.高考准考证原件、身份证、盖有学校公章的录取通知书；2.纸质档案，可以选择按当地政策邮寄（高中统一邮寄地址信息如下： 收件人：南航招生办 电话：025-52119050 单位名称：南京航空航天大学 收件地址：南京市江宁区将军大道 29 号 邮编：211106）或者报到时直接交给学院；3.党团员办理组织关系转移手续，团员携带团员证、入团志愿书，丢失需要中学出具团组织关系转接证明；4.近期免冠正面1寸彩照8张；5.户口迁移材料（自愿迁移才准备）。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-0332', '团员团组织关系转接怎么操作？', '请先查看新生群，导员是否发通知确认开启办理团组织关系转接，若已开始，以下为转接步骤：高中使用智慧团建系统的，将团组织关系转到“团江苏省委‑南京航空航天大学团委”下对应学院的支部；携带团员证、入团志愿书，如若丢失需要中学出具团组织关系转接证明。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-0333', '江苏省内党员组织关系如何转接？', '尽量通过全国党员信息管理系统转入就读学院党委/党支部，具体名称和学院确认。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-0334', '省外党员组织关系如何转接？', '如果全国党员信息管理系统和江苏通联，通过系统转入学院党委/党支部，名称和学院确认；未通联的，携带基层党委开具的纸质介绍信转到南京航空航天大学对应学院党委。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-0335', '新生户口迁移是强制的吗？', '自愿迁移原则。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-0336', '办理户口迁入需要哪些材料？', '身份证正反面复印件；1寸白底大头无框身份证标准照片1张，背面写姓名学号；录取通知书复印件；户口信息采集单；户口迁移证。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-0337', '户口迁移证填写有什么要求？', '出生地、籍贯要写详细到XX省XX市（县）；迁移地址填写江苏省南京市江宁区将军大道29号；要有户籍地公安机关户口专用章，信息要和录取通知书一致。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-0338', '新生入学资格复查在什么时间段，复查什么？', '入学后3个月内开展，复查考生身份证明、录取通知、考生档案信息是否一致，不一致会调查并按政策处理。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-0339', '天目湖校区可以邮寄行李的快递有哪些，收件地址是什么？', '顺丰、圆通、申通、中通、极兔、韵达、京东、中国邮政或邮政EMS；地址：江苏省常州市溧阳市古县街道滨河东路29号南京航空航天大学天目湖校区，填写学院、姓名、手机号。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-0340', '行李邮寄有哪些注意事项？', '邮寄费自理；准确填写本人姓名和可收短信的手机号；包裹粘贴新生行李专用标签，标签可以复印，保存寄件单号；到校带身份证，下载菜鸟或淘宝APP，凭取件码取件；建议提前1‑2天邮寄。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-0341', '天目湖校区菜鸟驿站咨询电话？', '18961246211。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-0342', '新生需要缴纳哪些费用？', '学费、住宿费，以及军训服装费、体检费、大学生医保费等代办费。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-0343', '住宿费收费标准是多少？', '每生每年1200元‑1500元，楼栋不同标准不同，学校统一安排。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-0344', '代办费收取规则是什么？', '据实收取，多退少补；大学生医保按每年270元一次性收取；低保学生或者不同意参保的，开学后走流程办理退款。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-0345', '缴费截止日期是什么时候？', '2026年9月1日。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-0346', '电脑端缴费网址是什么？', 'http://jaofei.nuaa.edu.cn', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-0347', '手机端怎么缴费？', '微信搜索公众号“南京航空航天大学智慧校园”，点击校园缴费；或者微信、支付宝扫描对应二维码，统一身份认证登录校园统一支付平台，勾选缴费项目付款。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-0348', '缴费之后票据怎么获取查验？', '平台下载电子票据；登录财政部电子票据公共服务平台http//pjcy.mof.gov.cn，输入票据代码、票据号码、校验码查验。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-0349', '没有交通银行卡的新生银行卡如何处理？', '学校随录取通知书寄送预开的交通银行太平洋借记卡，无初始密码，需要激活；可以到附近交行网点激活，报到期间校内有激活点，错过的需要本人带身份证去校外网点激活。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-0350', '已经有交通银行卡的新生要做什么？', '学校不再办卡；自行登录统一支付平台登记自己的交通银行卡号，到校激活未启用的银行卡。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-0351', '交通银行卡有什么用途，遗失怎么办？', '用于学杂费结算、校园卡充值、奖学金助学金补助勤工酬金贷款发放；不要随意注销更换；遗失补办之后要在统一支付平台更新卡号。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-0352', '交行卡相关咨询电话？', '交行客服95559；交行御道街支行025‑84891950、025‑83139685。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-0353', '学校财务收费咨询电话？', '025‑84892239，025‑84892722。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-0354', '军训服怎么退费？', '请拨打南航财务处电话咨询退费。025‑84892239或025‑84892722。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-0355', '卧具用品怎么获取？', '可以自愿选购学校代购的卧具，也可以按照清单规格自备床上用品。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-0356', '统一身份认证系统有什么作用？', '一套账号密码访问校内所有系统、网络。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-0357', '统一身份认证怎么激活？', '访问对应网址，点击新用户认证，完善个人信息完成激活。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-0358', '忘记统一身份认证密码怎么办？', '访问对应网页，点击忘记密码重置。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-0359', 'i南航APP可以做什么，如何下载？', '可以查看校园地图、校史、通知公告，校园卡充值、场馆预约、办理政审证明；可以扫描文档二维码下载，也可以在手机应用市场搜索“南航”下载。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-0360', '智慧门户有哪几种访问形式？', 'i南航APP；“南京航空航天大学智慧门户”微信企业微信号；智慧门户网页版http://i.nuaa.edu.cn', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-0361', '校园卡业务办理渠道有哪些？', '人工窗口、自动服务终端、i南航APP。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-0362', '天目湖校区校园卡人工窗口在哪里？', '师生服务大厅16号窗口。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-0363', '虚拟校园卡怎么领取？', '拿到实体校园卡后，下载i南航APP或者关注“南京航空航天大学智慧门户”微信企业号领取。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-0364', '校园卡怎么充值？', 'i南航APP首页校园卡，支持微信、支付宝、绑定后的交通银行银行卡充值。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-0365', '微信怎么绑定校园卡？', '微信企业号“南京航空航天大学智慧门户”找到校园卡应用，登录成功即完成绑定。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-0366', '支付宝怎么绑定校园卡？', '支付宝扫描对应二维码，点击去绑定，学校', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-0367', '在哪里可以做新生信息预报到？', '登录迎新系统可以做新生信息预报到。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-0368', '在哪里办理户口迁移信息登记？', '登录迎新系统可以办理户口迁移信息登记。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-0369', '哪里可以订购宿舍用品？', '登录迎新系统可以订购宿舍用品。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-0370', '家庭经济困难学生绿色通道在哪里办理？', '登录迎新系统可以办理家庭经济困难学生绿色通道相关工作。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-0371', '在哪里可以查询个人班级？', '登录迎新系统可以查询个人班级。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-0372', '在哪里可以查询学号？', '登录迎新系统可以查询学号。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-0373', '在哪里可以查询宿舍分配信息？', '登录迎新系统可以查询宿舍分配。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-0374', '在哪里可以查询缴费标准？', '登录迎新系统可以查询缴费标准。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-0375', '在哪里可以查询报到地点？', '登录迎新系统可以查询报到地点。', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-0376', '宿舍最早多久可以入住？', '8月29日', 'resolved', '2026-08-06');
INSERT INTO qa_entries (id, question, answer, status, created_at) VALUES ('qa-2026-0377', '天目湖校区宿舍床尺寸大小？', '靠近储物柜一侧为200*90，靠近淋浴间一侧为190*90', 'resolved', '2026-08-06');
